/bin/bash -lc "cat > .tmp/an.py <<'PY'
import numpy as np
x=np.load('source_pixels.npz')['rgb'].astype(np.int16)
med=np.median(x,axis=0).astype(np.int16)
for t in range(96):
 d=np.max(abs(x[t]-med),axis=2); m=d>10
 seen=np.zeros(m.shape,bool); comps=[]
 for y0,x0 in zip(*np.where(m)):
  if seen[y0,x0]:continue
  st=[(y0,x0)];seen[y0,x0]=1; pts=[]
  while st:
   y1,x1=st.pop();pts.append((y1,x1))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    yy,xx=y1+dy,x1+dx
    if 0<=yy<144 and 0<=xx<256 and m[yy,xx] and not seen[yy,xx]:seen[yy,xx]=1;st.append((yy,xx))
  if len(pts)>=3: comps.append(pts)
 comps.sort(key=len,reverse=True)
 if t%2==0 or t<5:
  desc=[]
  for p in comps[:4]:
   ys=[q[0] for q in p];xs=[q[1] for q in p];desc.append((len(p),(min(xs),min(ys),max(xs),max(ys))))
  yy,xx=np.where(d>20)
  print(t,'d>10',m.sum(),desc,'d20box', (xx.min(),yy.min(),xx.max(),yy.max()) if len(xx) else None)
PY
python .tmp/an.py"
